import{_ as e,o as s,c as r,S as n}from"./chunks/framework.D1Ss-Xl7.js";const v=JSON.parse('{"title":"JavaScript对象的常见操作","description":"","frontmatter":{"title":"JavaScript对象的常见操作","date":"2017-06-18 22:13","comments":true,"archives":2017,"tags":["js"]},"headers":[],"relativePath":"posts/2017-06-18-javascript-object/index.md","filePath":"posts/2017/2017-06-18-JavaScript-Object.md"}'),t={name:"posts/2017-06-18-javascript-object/index.md"};function p(l,a,o,c,i,b){return s(),r("div",null,[...a[0]||(a[0]=[n(`<p>工作也算是稳定了，不过理想和现实的差距还是很大。程序员的职责是把枯燥的工作自动化，而不是去进行重复劳动。最近在写 JavaScript 程序的时候，遇到了很多对象相关的操作。所以写点东西来总结下这半个月的成长。</p><h2 id="javascript-对象复制" tabindex="-1">JavaScript 对象复制 <a class="header-anchor" href="#javascript-对象复制" aria-label="Permalink to &quot;JavaScript 对象复制&quot;">​</a></h2><p>JavaScript 对象默认全部是拷贝引用，也就是所谓的浅拷贝。所以我们在对象操作的时候，要记住是否需要进行拷贝。一般我们使用对象的时候，都是需要对其某个属性进行修改。所以正确的写法是：</p><div class="language-js line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#D73A49;">const</span><span style="color:#005CC5;"> bar</span><span style="color:#D73A49;"> =</span><span style="color:#24292E;"> { a: </span><span style="color:#005CC5;">1</span><span style="color:#24292E;">, b: </span><span style="color:#005CC5;">2</span><span style="color:#24292E;">， c: {d: </span><span style="color:#005CC5;">4</span><span style="color:#24292E;">}}</span></span>
<span class="line"><span style="color:#D73A49;">const</span><span style="color:#005CC5;"> foo</span><span style="color:#D73A49;"> =</span><span style="color:#24292E;"> {</span><span style="color:#D73A49;">...</span><span style="color:#24292E;">bar, b: </span><span style="color:#005CC5;">3</span><span style="color:#24292E;">}</span></span>
<span class="line"><span style="color:#24292E;">foo.c.d </span><span style="color:#D73A49;">=</span><span style="color:#005CC5;">10</span></span>
<span class="line"><span style="color:#24292E;">console.</span><span style="color:#6F42C1;">log</span><span style="color:#24292E;">(bar.c.d)</span></span>
<span class="line"><span style="color:#6A737D;">// { a: 1, b: 2， c: {d: 10}}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>这样就同时进行拷贝和修改。注意这里使用的是 JavaScript 的 es6 语法。如果要在浏览器运行，你需要 <a href="https://babeljs.io/repl/" target="_blank" rel="noreferrer">Babel</a> 来进行转换。注意，如果对象里面还有对象的话，这种方式也仅仅是浅拷贝。深拷贝必须遍历所有属性进行复制，在效率上有很大问题，所以我们尽量不要去用深度拷贝来解决问题。 这里对象的复制是使用的<a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Object/assign" target="_blank" rel="noreferrer">Object.assign</a> 针对对象的简单类型可以进行复制，但是对象还是引用。如果实际的应用场景确实需要进行深度拷贝，可以使用<a href="https://lodash.com/" target="_blank" rel="noreferrer">Lodash</a>。提供了很多常用的类库。</p><h2 id="javascript-数组" tabindex="-1">JavaScript 数组 <a class="header-anchor" href="#javascript-数组" aria-label="Permalink to &quot;JavaScript 数组&quot;">​</a></h2><p>针对数组，现在已经不推荐用 for 循环来进行处理了，请使用数组的<a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Array/map" target="_blank" rel="noreferrer">map</a>, <a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Array/filter" target="_blank" rel="noreferrer">filter</a>，<a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Array/Reduce" target="_blank" rel="noreferrer">reduce</a>来处理数组的操作。相信这三个方法足以满足需求。</p><h2 id="javascript-开发规范" tabindex="-1">JavaScript 开发规范 <a class="header-anchor" href="#javascript-开发规范" aria-label="Permalink to &quot;JavaScript 开发规范&quot;">​</a></h2><p>现在 JavaScript 已经是 es6 的时代，所以我们也需要顺应时代学习新知识。这里我建议大家读读 airbnb 的<a href="https://github.com/airbnb/javascript" target="_blank" rel="noreferrer">JavaScript Style Guide</a>。这里不仅教会你正确的编码格式，更多的是优秀的写法。如何合理的拷贝对象，遍历数组等等。</p><p>目前就写到这里，工作之后并没有多少成长。写博客都发呆了很久该写什么。。。</p>`,10)])])}const h=e(t,[["render",p]]);export{v as __pageData,h as default};
